// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/healthz", wrapper.Healthz)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/ping", wrapper.Ping)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v1/admin/session", wrapper.SignOut)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/admin/session", wrapper.SignIn)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/admin/me", wrapper.GetMe)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/admin/catalog", wrapper.GetCatalog)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/admin/categories", wrapper.CreateCategory)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v1/admin/categories/{id}", wrapper.DeleteCategory)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/v1/admin/categories/{id}", wrapper.UpdateCategory)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/admin/categories/{id}/move", wrapper.MoveCategory)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/admin/items", wrapper.CreateItem)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v1/admin/items/{id}", wrapper.DeleteItem)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/v1/admin/items/{id}", wrapper.UpdateItem)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/admin/items/{id}/move", wrapper.MoveItem)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/admin/modifier-groups", wrapper.CreateModifierGroup)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v1/admin/modifier-groups/{id}", wrapper.DeleteModifierGroup)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/v1/admin/modifier-groups/{id}", wrapper.UpdateModifierGroup)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/admin/modifier-groups/{id}/move", wrapper.MoveModifierGroup)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/admin/staff", wrapper.ListStaff)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/admin/staff", wrapper.CreateStaff)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/v1/admin/staff/{id}", wrapper.UpdateStaff)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/admin/terminals", wrapper.ListTerminals)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/admin/terminals", wrapper.CreateTerminal)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/admin/terminals/{id}/pairing-code", wrapper.CreatePairingCode)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v1/admin/terminals/{id}", wrapper.UnpairTerminal)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/terminal/pair", wrapper.PairTerminal)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/terminal/changes", wrapper.GetChanges)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/terminal/events", wrapper.SendEvents)

	return m
}
